import{_ as t,o as a,c as d,ag as o}from"./chunks/framework.8haY-N6i.js";const u=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1794899297000}'),r={name:"reference/cli.md"};function i(c,e,n,s,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><div><p><code>rustcms</code> creates applications and generates code. Other commands run inside the application in the current directory (<code>cargo run -- &lt;command&gt;</code>), or with its binary (<code>./blog &lt;command&gt;</code>); <code>cargo run -- --help</code> lists them all, the application&#39;s own included.</p><h2 id="global-commands" tabindex="-1">Global commands <a class="header-anchor" href="#global-commands" aria-label="Permalink to &quot;Global commands&quot;">​</a></h2><h3 id="new" tabindex="-1"><code>new</code> <a class="header-anchor" href="#new" aria-label="Permalink to &quot;`new`&quot;">​</a></h3><p>Create a new application</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Package name (lowercase letters, digits, <code>-</code> and <code>_</code>)</td></tr><tr><td><code>--path</code></td><td>Parent directory (default: <code>.</code>)</td></tr><tr><td><code>--in-workspace</code></td><td>Do not declare a standalone <code>[workspace]</code> (for apps inside another workspace)</td></tr><tr><td><code>--no-fetch</code></td><td>Do not resolve the dependencies (<code>Cargo.lock</code> is written on the first build)</td></tr></tbody></table><h3 id="makemodel" tabindex="-1"><code>make:model</code> <a class="header-anchor" href="#makemodel" aria-label="Permalink to &quot;`make:model`&quot;">​</a></h3><p>Create a SeaORM entity in <code>src/models</code></p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Model name in PascalCase, e.g. <code>BlogPost</code></td></tr><tr><td><code>-m, --migration</code></td><td>Also create a <code>create_&lt;table&gt;_table</code> migration</td></tr></tbody></table><h3 id="makeresource" tabindex="-1"><code>make:resource</code> <a class="header-anchor" href="#makeresource" aria-label="Permalink to &quot;`make:resource`&quot;">​</a></h3><p>Create an admin resource in <code>src/admin/resources</code> for a model</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;model&gt;</code></td><td>Model name in PascalCase (the model must exist in <code>src/models</code>)</td></tr><tr><td><code>--generate</code></td><td>Generate fields, form, table and filters from the model&#39;s columns</td></tr><tr><td><code>--belongs-to</code></td><td>Relationship select for a column: <code>category_id=categories</code> (repeatable)</td></tr></tbody></table><h3 id="makepolicy" tabindex="-1"><code>make:policy</code> <a class="header-anchor" href="#makepolicy" aria-label="Permalink to &quot;`make:policy`&quot;">​</a></h3><p>Create a policy in <code>src/policies</code></p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Policy name in PascalCase, e.g. <code>PostPolicy</code></td></tr></tbody></table><h3 id="makemigration" tabindex="-1"><code>make:migration</code> <a class="header-anchor" href="#makemigration" aria-label="Permalink to &quot;`make:migration`&quot;">​</a></h3><p>Create a migration in <code>src/database/migrations</code></p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>snake_case name; <code>create_&lt;table&gt;_table</code> generates a table skeleton</td></tr></tbody></table><h3 id="maketest" tabindex="-1"><code>make:test</code> <a class="header-anchor" href="#maketest" aria-label="Permalink to &quot;`make:test`&quot;">​</a></h3><p>Create a feature test in <code>tests/feature</code></p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Test name in PascalCase, e.g. <code>PostAdminTest</code></td></tr></tbody></table><h3 id="makeapi" tabindex="-1"><code>make:api</code> <a class="header-anchor" href="#makeapi" aria-label="Permalink to &quot;`make:api`&quot;">​</a></h3><p>Create a JSON API for a model: controller, JSON resource and routes (list and show)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;model&gt;</code></td><td>Model name in PascalCase (the model must exist in <code>src/models</code>)</td></tr></tbody></table><h3 id="makeservice" tabindex="-1"><code>make:service</code> <a class="header-anchor" href="#makeservice" aria-label="Permalink to &quot;`make:service`&quot;">​</a></h3><p>Create a service (business rules) in <code>src/services</code></p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Name ending in <code>Service</code>, e.g. <code>EnrollmentService</code></td></tr></tbody></table><h3 id="makejob" tabindex="-1"><code>make:job</code> <a class="header-anchor" href="#makejob" aria-label="Permalink to &quot;`make:job`&quot;">​</a></h3><p>Create a background job in <code>src/jobs</code> and register it</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Job name in PascalCase, e.g. <code>SendWelcome</code></td></tr></tbody></table><h3 id="makeseeder" tabindex="-1"><code>make:seeder</code> <a class="header-anchor" href="#makeseeder" aria-label="Permalink to &quot;`make:seeder`&quot;">​</a></h3><p>Create a seeder in <code>src/database/seeders</code> and register it</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Name ending in <code>Seeder</code>, e.g. <code>CourseSeeder</code></td></tr></tbody></table><h3 id="makefactory" tabindex="-1"><code>make:factory</code> <a class="header-anchor" href="#makefactory" aria-label="Permalink to &quot;`make:factory`&quot;">​</a></h3><p>Create a model factory in <code>src/database/factories</code></p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;model&gt;</code></td><td>Model name in PascalCase (the model must exist in <code>src/models</code>)</td></tr></tbody></table><h3 id="makesettings" tabindex="-1"><code>make:settings</code> <a class="header-anchor" href="#makesettings" aria-label="Permalink to &quot;`make:settings`&quot;">​</a></h3><p>Create a settings group (<code>src/settings</code>) and its admin page (<code>src/admin/pages</code>)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Name ending in <code>Settings</code>, e.g. <code>SchoolSettings</code></td></tr></tbody></table><h3 id="makecommand" tabindex="-1"><code>make:command</code> <a class="header-anchor" href="#makecommand" aria-label="Permalink to &quot;`make:command`&quot;">​</a></h3><p>Create a console command in <code>src/console</code> and register it</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Command name, e.g. <code>lms:report</code></td></tr></tbody></table><h3 id="makepage" tabindex="-1"><code>make:page</code> <a class="header-anchor" href="#makepage" aria-label="Permalink to &quot;`make:page`&quot;">​</a></h3><p>Create a custom admin page: <code>src/admin/pages</code> + a template in <code>resources/views/admin</code> (or a script)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Name ending in <code>Page</code>, e.g. <code>CourseOverviewPage</code></td></tr><tr><td><code>--script</code></td><td>Draw it with an extension script (<code>resources/admin/js</code>) instead of a template</td></tr><tr><td><code>--react</code></td><td>Draw it with a React component (<code>resources/admin/src</code>, host API v2, built with npm)</td></tr></tbody></table><h3 id="makesdk" tabindex="-1"><code>make:sdk</code> <a class="header-anchor" href="#makesdk" aria-label="Permalink to &quot;`make:sdk`&quot;">​</a></h3><p>Install or update the admin SDK in <code>resources/admin/sdk</code> (edited files are kept)</p><h3 id="makewidget" tabindex="-1"><code>make:widget</code> <a class="header-anchor" href="#makewidget" aria-label="Permalink to &quot;`make:widget`&quot;">​</a></h3><p>Create an admin widget script in <code>resources/admin/js</code></p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Widget name, <code>vendor/name</code>, e.g. <code>acme/color</code></td></tr></tbody></table><h3 id="doctor" tabindex="-1"><code>doctor</code> <a class="header-anchor" href="#doctor" aria-label="Permalink to &quot;`doctor`&quot;">​</a></h3><p>Check that this machine can build an application</p><h3 id="upgrade" tabindex="-1"><code>upgrade</code> <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;`upgrade`&quot;">​</a></h3><p>Move the application to this command&#39;s RustCMS version (Cargo.toml and Cargo.lock)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--dry-run</code></td><td>Show the changes without writing them</td></tr><tr><td><code>--force</code></td><td>Allow going back to an older version</td></tr></tbody></table><h3 id="self-update" tabindex="-1"><code>self-update</code> <a class="header-anchor" href="#self-update" aria-label="Permalink to &quot;`self-update`&quot;">​</a></h3><p>Replace this command with the latest release (installed by install.sh)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--version</code></td><td>A given release instead of the latest, e.g. <code>v0.4.0</code> (may be older)</td></tr></tbody></table><h3 id="docs" tabindex="-1"><code>docs</code> <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;`docs`&quot;">​</a></h3><p>Open the guide of this version in a browser</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--print-path</code></td><td>Print its URL instead of opening it</td></tr></tbody></table><h3 id="docscli" tabindex="-1"><code>docs:cli</code> <a class="header-anchor" href="#docscli" aria-label="Permalink to &quot;`docs:cli`&quot;">​</a></h3><p>Print the command reference as Markdown</p><h2 id="application-commands" tabindex="-1">Application commands <a class="header-anchor" href="#application-commands" aria-label="Permalink to &quot;Application commands&quot;">​</a></h2><h3 id="serve" tabindex="-1"><code>serve</code> <a class="header-anchor" href="#serve" aria-label="Permalink to &quot;`serve`&quot;">​</a></h3><p>Start the HTTP server</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--listen</code></td><td>Address to listen on (default: <code>app.listen</code>)</td></tr><tr><td><code>--api-only</code></td><td>Serve the application API only, without the admin panel (<code>app.mode = &quot;api&quot;</code>)</td></tr><tr><td><code>--watch</code></td><td>With <code>rustcms</code> only (macOS, Linux): rebuild and replace the server when the application&#39;s files change; a failed build keeps the running server</td></tr></tbody></table><h3 id="migrate" tabindex="-1"><code>migrate</code> <a class="header-anchor" href="#migrate" aria-label="Permalink to &quot;`migrate`&quot;">​</a></h3><p>Run pending migrations</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--allow-newer</code></td><td>Accept migrations applied by a newer version (after a rollback): they are logged and left as they are; this version&#39;s pending ones run</td></tr></tbody></table><h3 id="migraterollback" tabindex="-1"><code>migrate:rollback</code> <a class="header-anchor" href="#migraterollback" aria-label="Permalink to &quot;`migrate:rollback`&quot;">​</a></h3><p>Roll back the last migrations</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--step</code></td><td>Number of migrations to roll back (default: <code>1</code>)</td></tr></tbody></table><h3 id="migratefresh" tabindex="-1"><code>migrate:fresh</code> <a class="header-anchor" href="#migratefresh" aria-label="Permalink to &quot;`migrate:fresh`&quot;">​</a></h3><p>Drop all tables and re-run every migration</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--force</code></td><td>Required in production</td></tr><tr><td><code>--seed</code></td><td>Run the <code>database</code> seeder afterwards</td></tr></tbody></table><h3 id="migraterefresh" tabindex="-1"><code>migrate:refresh</code> <a class="header-anchor" href="#migraterefresh" aria-label="Permalink to &quot;`migrate:refresh`&quot;">​</a></h3><p>Roll back every migration and run them again</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--force</code></td><td>Required in production</td></tr></tbody></table><h3 id="migratestatus" tabindex="-1"><code>migrate:status</code> <a class="header-anchor" href="#migratestatus" aria-label="Permalink to &quot;`migrate:status`&quot;">​</a></h3><p>Show applied and pending migrations</p><h3 id="dbseed" tabindex="-1"><code>db:seed</code> <a class="header-anchor" href="#dbseed" aria-label="Permalink to &quot;`db:seed`&quot;">​</a></h3><p>Seed the database (the <code>database</code> seeder, or <code>--class &lt;name&gt;</code>)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--class</code></td><td>Seeder to run (default: <code>database</code>)</td></tr><tr><td><code>--force</code></td><td>Required in production</td></tr></tbody></table><h3 id="routelist" tabindex="-1"><code>route:list</code> <a class="header-anchor" href="#routelist" aria-label="Permalink to &quot;`route:list`&quot;">​</a></h3><p>List the HTTP routes described by the framework, providers and the application</p><h3 id="keygenerate" tabindex="-1"><code>key:generate</code> <a class="header-anchor" href="#keygenerate" aria-label="Permalink to &quot;`key:generate`&quot;">​</a></h3><p>Generate APP_KEY and write it to .env</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--show</code></td><td>Print the key instead of writing .env</td></tr><tr><td><code>--force</code></td><td>Replace an existing APP_KEY</td></tr></tbody></table><h3 id="queuework" tabindex="-1"><code>queue:work</code> <a class="header-anchor" href="#queuework" aria-label="Permalink to &quot;`queue:work`&quot;">​</a></h3><p>Run queued jobs until stopped (Ctrl-C / SIGTERM lets running jobs finish)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--queue</code></td><td>Queue to take jobs from (repeatable; default: queue.queues)</td></tr><tr><td><code>--once</code></td><td>Run the jobs ready now (at most 1,000), then exit</td></tr><tr><td><code>--workers</code></td><td>Workers (default: queue.workers)</td></tr></tbody></table><h3 id="queuefailed" tabindex="-1"><code>queue:failed</code> <a class="header-anchor" href="#queuefailed" aria-label="Permalink to &quot;`queue:failed`&quot;">​</a></h3><p>List failed jobs</p><h3 id="queueretry" tabindex="-1"><code>queue:retry</code> <a class="header-anchor" href="#queueretry" aria-label="Permalink to &quot;`queue:retry`&quot;">​</a></h3><p>Run failed jobs again (attempts start over)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;id&gt;</code></td><td>Job id</td></tr><tr><td><code>--all</code></td><td>Every failed job</td></tr></tbody></table><h3 id="queueforget" tabindex="-1"><code>queue:forget</code> <a class="header-anchor" href="#queueforget" aria-label="Permalink to &quot;`queue:forget`&quot;">​</a></h3><p>Delete failed jobs</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;id&gt;</code></td><td>Job id</td></tr><tr><td><code>--all</code></td><td>Every failed job</td></tr></tbody></table><h3 id="keyreencrypt" tabindex="-1"><code>key:reencrypt</code> <a class="header-anchor" href="#keyreencrypt" aria-label="Permalink to &quot;`key:reencrypt`&quot;">​</a></h3><p>Seal every encrypted column and settings secret with APP_KEY (after a rotation)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--dry-run</code></td><td>Check and count; write nothing</td></tr><tr><td><code>--list</code></td><td>List the encrypted columns and exit</td></tr><tr><td><code>--batch</code></td><td>Rows read at a time (default: <code>500</code>)</td></tr></tbody></table><h3 id="schedulelist" tabindex="-1"><code>schedule:list</code> <a class="header-anchor" href="#schedulelist" aria-label="Permalink to &quot;`schedule:list`&quot;">​</a></h3><p>List the schedules, their next slot and their last claimed slot</p><h3 id="schedulerun" tabindex="-1"><code>schedule:run</code> <a class="header-anchor" href="#schedulerun" aria-label="Permalink to &quot;`schedule:run`&quot;">​</a></h3><p>Run a schedule now (a manual run: no slot claim, no grace, no without_overlapping; a job is enqueued for the workers, a run runs here)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>The schedule&#39;s name</td></tr></tbody></table><h2 id="auth-commands" tabindex="-1">Auth commands <a class="header-anchor" href="#auth-commands" aria-label="Permalink to &quot;Auth commands&quot;">​</a></h2><p>Added by <code>AuthProvider</code> (registered in new applications).</p><h3 id="makeuser" tabindex="-1"><code>make:user</code> <a class="header-anchor" href="#makeuser" aria-label="Permalink to &quot;`make:user`&quot;">​</a></h3><p>Create a user (prints a generated password if none is given)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--email</code></td><td>Sign-in email</td></tr><tr><td><code>--name</code></td><td>Display name</td></tr><tr><td><code>--password</code></td><td>Password (default: generated)</td></tr><tr><td><code>--super-admin</code></td><td>Grant the super_admin role</td></tr><tr><td><code>--guard</code></td><td>Guard of the super_admin role (default: <code>admin</code>)</td></tr></tbody></table><h3 id="roleassign" tabindex="-1"><code>role:assign</code> <a class="header-anchor" href="#roleassign" aria-label="Permalink to &quot;`role:assign`&quot;">​</a></h3><p>Give an existing user a role (<code>super_admin</code> or any role) of a guard</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--email</code></td><td>User email</td></tr><tr><td><code>--role</code></td><td>Role name, e.g. <code>super_admin</code></td></tr><tr><td><code>--guard</code></td><td>Guard of the role (<code>admin</code>, <code>api</code>) (default: <code>admin</code>)</td></tr></tbody></table><h3 id="tokencreate" tabindex="-1"><code>token:create</code> <a class="header-anchor" href="#tokencreate" aria-label="Permalink to &quot;`token:create`&quot;">​</a></h3><p>Issue an API token for a user (printed once)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>--email</code></td><td>Owner email</td></tr><tr><td><code>--name</code></td><td>Token label</td></tr><tr><td><code>--abilities</code></td><td>Comma-separated abilities (default: <code>*</code>)</td></tr><tr><td><code>--expires-days</code></td><td>Lifetime in days (1 to 3650)</td></tr></tbody></table><h3 id="permissionsync" tabindex="-1"><code>permission:sync</code> <a class="header-anchor" href="#permissionsync" aria-label="Permalink to &quot;`permission:sync`&quot;">​</a></h3><p>Create declared permissions and mark undeclared ones orphaned</p><h3 id="sessionprune" tabindex="-1"><code>session:prune</code> <a class="header-anchor" href="#sessionprune" aria-label="Permalink to &quot;`session:prune`&quot;">​</a></h3><p>Delete expired admin sessions and ended JWT sign-ins</p><h3 id="auditprune" tabindex="-1"><code>audit:prune</code> <a class="header-anchor" href="#auditprune" aria-label="Permalink to &quot;`audit:prune`&quot;">​</a></h3><p>Delete audit log entries older than audit.retention_days (also done hourly by <code>serve</code>)</p><h2 id="admin-panel-commands" tabindex="-1">Admin panel commands <a class="header-anchor" href="#admin-panel-commands" aria-label="Permalink to &quot;Admin panel commands&quot;">​</a></h2><p>Added by <code>AdminProvider</code> (<code>media:prune</code> with <code>media()</code>).</p><h3 id="idempotencyprune" tabindex="-1"><code>idempotency:prune</code> <a class="header-anchor" href="#idempotencyprune" aria-label="Permalink to &quot;`idempotency:prune`&quot;">​</a></h3><p>Delete expired idempotency keys of admin writes</p><h3 id="mediaprune" tabindex="-1"><code>media:prune</code> <a class="header-anchor" href="#mediaprune" aria-label="Permalink to &quot;`media:prune`&quot;">​</a></h3><p>Delete queued media files and abandoned uploads</p><h3 id="langmissing" tabindex="-1"><code>lang:missing</code> <a class="header-anchor" href="#langmissing" aria-label="Permalink to &quot;`lang:missing`&quot;">​</a></h3><p>List the admin labels without a translation, as TOML to add to the catalog (lang/vi.toml, …)</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;locale&gt;</code></td><td>Language, e.g. <code>vi</code></td></tr></tbody></table><h3 id="adminbranding" tabindex="-1"><code>admin:branding</code> <a class="header-anchor" href="#adminbranding" aria-label="Permalink to &quot;`admin:branding`&quot;">​</a></h3><p>Show where the panel&#39;s branding comes from, and load it once to check it (changes nothing)</p></div>',2)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
